<template><FormSection :title="t('settings.proxy')"><label><input data-action="proxy-enable" type="checkbox" :checked="modelValue.enabled" @change="change('enabled',$event.target.checked)"> {{t('settings.proxy_enable')}}</label><label>HTTP <input aria-label="HTTP proxy" :placeholder="t('settings.proxy_placeholder')" :disabled="!modelValue.enabled" :value="modelValue.http" @input="change('http',$event.target.value)"></label><label>HTTPS <input aria-label="HTTPS proxy" :placeholder="t('settings.proxy_placeholder')" :disabled="!modelValue.enabled" :value="modelValue.https" @input="change('https',$event.target.value)"></label><label>No Proxy <input aria-label="No proxy" :placeholder="t('settings.proxy_noproxy_placeholder')" :disabled="!modelValue.enabled" :value="modelValue.noProxy" @input="change('noProxy',$event.target.value)"></label><StatusBadge v-if="result" :tone="result.success?'success':'error'">{{result.message}}</StatusBadge><div v-if="probes && probes.length" class="proxy-probes"><strong>{{ t('settings.proxy_probe_title') }}</strong><button v-for="probe in probes" :key="probe.port" class="proxy-probe-row" :class="{'proxy-probe-row--ok':probe.ok}" type="button" @click="$emit('apply-probe', probe.url)"><span class="proxy-probe-row__url">{{ probe.url }}</span><span class="proxy-probe-row__msg">{{ probe.message }}</span><span v-if="probe.ok" class="proxy-probe-row__use">{{ t('settings.proxy_probe_use') }}</span></button></div><template #actions><button class="xdev-btn xdev-btn--secondary" data-action="proxy-probe" type="button" @click="$emit('probe')">{{t('settings.proxy_probe')}}</button><button class="xdev-btn xdev-btn--secondary" data-action="proxy-test" type="button" @click="$emit('test')">{{t('settings.proxy_test')}}</button><button class="xdev-btn xdev-btn--secondary" data-action="proxy-save" type="button" @click="$emit('save')">{{t('btn.save')}}</button></template></FormSection></template>
<script setup>import FormSection from '../FormSection.vue';import StatusBadge from '../StatusBadge.vue';const p=defineProps({modelValue:{type:Object,required:true},result:Object,probes:{type:Array,default:()=>[]},t:{type:Function,required:true}});const e=defineEmits(['update:modelValue','test','save','probe','apply-probe']);const change=(k,v)=>e('update:modelValue',{...p.modelValue,[k]:v});</script>
<style scoped>.form-section :deep(label){display:grid;grid-template-columns:80px minmax(0,1fr);align-items:center;gap:var(--xdev-space-3);color:var(--xdev-text-secondary)}.form-section :deep(label:first-child){display:flex;align-items:center}.form-section :deep(input:not([type="checkbox"])){width:100%;min-width:0;min-height:34px;padding:0 var(--xdev-space-3);border:1px solid var(--xdev-border-subtle);border-radius:var(--xdev-radius-sm);background:var(--xdev-bg-panel);color:var(--xdev-text-primary);font-size:var(--xdev-font-size-md)}.form-section :deep(input:focus){border-color:var(--xdev-accent)}.form-section :deep(.form-section__actions){flex-wrap:wrap}.form-section :deep(.form-section__actions) button{min-height:34px;padding:0 var(--xdev-space-3);min-width:96px}.proxy-probes{display:grid;gap:6px;margin-top:var(--xdev-space-3)}.proxy-probes strong{font-size:var(--xdev-font-size-sm);color:var(--xdev-text-secondary)}.proxy-probe-row{display:grid;grid-template-columns:auto 1fr auto;gap:var(--xdev-space-3);align-items:center;text-align:left;padding:6px var(--xdev-space-3);border:1px solid var(--xdev-border-subtle);border-radius:var(--xdev-radius-sm);background:var(--xdev-bg-panel);color:var(--xdev-text-primary);font-size:var(--xdev-font-size-sm);cursor:pointer}.proxy-probe-row:hover{border-color:var(--xdev-accent)}.proxy-probe-row--ok{border-color:var(--xdev-success)}.proxy-probe-row__url{font-family:var(--xdev-font-mono);color:var(--xdev-text-primary)}.proxy-probe-row__msg{color:var(--xdev-text-muted)}.proxy-probe-row--ok .proxy-probe-row__use{color:var(--xdev-success)}@media(max-width:560px){.form-section :deep(label:not(:first-child)){grid-template-columns:1fr;gap:var(--xdev-space-1);align-items:stretch}.proxy-probe-row{grid-template-columns:1fr auto}}</style>
